Translate("zhCN", "the-barrens", {
	title = "贫瘠之地",
	aliases = { "贫瘠荒原" },
	sections = {
		{
			title = "概述",
			text = [=[贫瘠之地是{link:kalimdor}卡利姆多{/link}腹地一片辽阔的稀树草原，黄草、荆棘树与龟裂的红土连绵不绝。它北起{link:ashenvale}灰谷{/link}的森林，南抵{link:thousand-needles}千针石林{/link}的峡谷，西接{link:stonetalon-mountains}石爪山脉{/link}与{link:mulgore}莫高雷{/link}的悬崖，东至无尽之海的海岸。世间少有地方如此广阔、如此干旱，又如此充满噬人的生灵。科多兽与斑马成群穿行其间，狮子与迅猛龙在此猎食，十几个族群为零散的水源争斗不休。{link:horde}部落{/link}的每一条道路都经过这里，部落的每一个敌人也都熟知这里。]=],
		},
		{
			title = "起源",
			text = [=[牛头人的史官说，贫瘠之地曾是一片青翠丰饶的土地。很久以前，战争与灾变将它焚尽，只留下一具干枯的躯壳，如今在世者无人记得它别的模样。{link:tauren}牛头人{/link}世世代代在它的{link:burning-steppes}平原{/link}上漂泊，被{link:centaurs}半人马{/link}从一处营地追猎到另一处营地。{link:quilboar}野猪人{/link}在南方筑起荆棘巢穴，{link:harpies}鹰身人{/link}则栖居于西面的山丘。

{link:third-war}第三次战争{/link}之后，{link:orcs}兽人{/link}来到{link:kalimdor}卡利姆多{/link}，{link:thrall}萨尔{/link}带领他们穿越这片平原。在漫长的行军途中，他遇见了正遭半人马袭击的{link:cairne-bloodhoof}凯恩·血蹄{/link}及其族人，兽人护卫牛头人的车队，直到他们抵达{link:mulgore}莫高雷{/link}。{link:battle-of-mount-hyjal}海加尔山之战{/link}后，{link:horde}部落{/link}将贫瘠之地作为连接新家园的通道：东边是{link:orgrimmar}奥格瑞玛{/link}与{link:durotar}杜隆塔尔{/link}，西边是{link:thunder-bluff}雷霆崖{/link}。]=],
		},
		{
			title = "当今",
			text = [=[名义上，贫瘠之地属于{link:horde}部落{/link}；实际上，每座{link:stranglethorn-vale}山谷{/link}都归最强者所有。{link:the-crossroads}十字路口{/link}是一座设防的{link:orcs}兽人{/link}城镇，扼守中央。{link:camp-taurajo}陶拉祖营地{/link}的{link:tauren}牛头人{/link}守卫南方。{link:steamwheedle-cartel}热砂港{/link}的地精在{link:ratchet}棘齿城{/link}港口与各方通商。

敌人从四面八方逼近。{link:kolkar-centaurs}科卡尔半人马{/link}有了新的首领。{link:bristleback-quilboar}钢鬃{/link}与刺背{link:quilboar}野猪人{/link}既与部落交战，也彼此厮杀。{link:theramore-isle}塞拉摩{/link}的士兵据守海岸上的{link:northwatch-hold}北方城堡{/link}，{link:ironforge}铁炉堡{/link}的{link:dwarves}矮人{/link}在{link:bael-modan}巴尔莫丹{/link}挖掘，{link:venture-company}风险投资公司{/link}则在北方毒害一座湖泊。{link:burning-blade}火刃氏族{/link}的邪教徒在{link:dreadmist-peak}鬼雾峰{/link}举行仪式。最奇异的是，绿洲开始发生变化，德鲁伊们担心，大地之下有什么东西正在做梦。]=],
		},
		{
			title = "居民",
			text = [=[• {b}{link:horde}部落{/link}。{/b}{link:orcs}兽人{/link}步兵、{link:tauren}牛头人{/link}勇士、{link:trolls}巨魔{/link}斥候和几名{link:forsaken}被遗忘者{/link}药剂师守卫着哨所与道路。
• {b}{link:ratchet}棘齿城{/link}的地精。{/b}商人、工匠和打手，谁付钱就卖给谁。
• {b}{link:centaurs}半人马{/link}。{/b}{link:kolkar-centaurs}科卡尔部族{/link}袭扰绿洲与道路。
• {b}{link:quilboar}野猪人{/link}。{/b}{link:razormane-quilboar}钢鬃部族{/link}占据北方和南部的山岭，刺背部族占据中部。
• {b}{link:alliance}联盟{/link}。{/b}{link:northwatch-hold}北方城堡{/link}的海军陆战队和{link:bael-modan}巴尔莫丹{/link}的{link:dwarves}矮人{/link}。
• {b}{link:southsea-pirates}南海海盗{/link}。{/b}在{link:the-merchant-coast}商旅海岸{/link}扎营的海盗。
• {b}野兽。{/b}科多兽、斑马、陆行鸟、草原狮、阳鳞迅猛龙、{link:farmer-ray}雷{/link}霆蜥蜴和雷鹰。]=],
		},
		{
			title = "历史",
			text = [=[• {b}干涸之地。{/b}早在{link:orcs}兽人{/link}到来之前，贫瘠之地就已被战争与灾变焚烧、烤干。没有史书记载那是何时。
• {b}漫长的行军。{/b}{link:thrall}萨尔{/link}的兽人穿越{link:burning-steppes}平原{/link}，击退{link:centaurs}半人马{/link}，将{link:cairne-bloodhoof}凯恩{/link}的部族平安送到{link:mulgore}莫高雷{/link}。
• {b}{link:horde}部落{/link}之路。{/b}{link:battle-of-mount-hyjal}海加尔山之战{/link}后，兽人建起{link:the-crossroads}十字路口{/link}和{link:gold-road}黄金之路{/link}上的瞭望塔。地精{link:gazlowe}加兹鲁维{/link}用建造{link:orgrimmar}奥格瑞玛{/link}赚来的{link:ginro-hearthkindle}金{/link}子建立了{link:ratchet}棘齿城{/link}。
• {b}当今。{/b}新的绿洲从地底涌出，随之而来的是新的扭曲生物。]=],
		},
		{
			title = "平原传说",
			text = [=[• {link:tauren}牛头人{/link}为贫瘠之地的巨兽另取了名字：白雾埃其亚基是草原猫科之王，撼地者{link:lakota-windsong}拉克塔{/link}曼尼是最伟大的科多兽。
• 贫瘠之地的阳鳞迅猛龙比别处的同类更加狡猾。它们曾偷走用来支付{link:the-crossroads}十字路口{/link}守卫军饷的银子，至今无人能解释缘由。
• {link:camp-taurajo}陶拉祖营地{/link}笼中的一名{link:quilboar}野猪人{/link}仍掌握着阿迦玛甘的魔法。他以此换取对抛弃他的部族的复仇。]=],
		},
	},
})

Translate("zhCN", "the-crossroads", {
	title = "十字路口",
	sections = {
		{
			title = "概述",
			text = [=[十字路口是{link:horde}部落{/link}在{link:the-barrens}贫瘠之地{/link}的心脏，一座建在大道交汇处山丘上的{link:orcs}兽人{/link}小屋城镇，四周筑有围墙。一条路向北通往{link:the-mor-shan-rampart}莫尔杉壁垒{/link}和{link:ashenvale}灰谷{/link}，一条向东通往{link:durotar}杜隆塔尔{/link}和{link:ratchet}棘齿城{/link}，一条向南通往{link:camp-taurajo}陶拉祖营地{/link}，一条向西通往{link:stonetalon-mountains}石爪山脉{/link}和{link:mulgore}莫高雷{/link}。{link:thork}索克{/link}守卫着城墙，{link:sergra-darkthorn}瑟格拉·黑棘{/link}训练猎人，塔楼上的卫兵注视着草原，提防{link:centaurs}半人马{/link}。在这里，兽人、{link:tauren}牛头人{/link}德鲁伊和{link:forsaken}被遗忘者{/link}药剂师可能围坐在同一堆篝火旁，迪弗拉克的双足飞龙则把消息带往{link:orgrimmar}奥格瑞玛{/link}。近来，一家名为杜隆塔尔补给后勤部的商号在城墙正西方建起了一座贸易站。]=],
		},
	},
})

Translate("zhCN", "camp-taurajo", {
	title = "陶拉祖营地",
	aliases = { "陶拉祖" },
	sections = {
		{
			title = "概述",
			text = [=[陶拉祖营地是{link:the-barrens}贫瘠之地{/link}南部的{link:tauren}牛头人{/link}要塞，一圈帐篷与图腾坐落在通往{link:thousand-needles}千针石林{/link}的路上。它守护着通往{link:mulgore}莫高雷{/link}的{link:burning-steppes}平原{/link}，营中的勇士向四周的{link:quilboar}野猪人{/link}营地出击。猎人{link:jorn-skyseer}乔恩·星眼{/link}在此授艺，铁匠{link:tatternack-steelforge}塔特纳克·钢炉{/link}研究敌人的兵器，营地边缘的笼子里关着{link:mangletooth}碎牙{/link}，一个被自己部族弃之等死的野猪人。步兵洛格玛近来听说，来自{link:dustwallow-marsh}尘泥沼泽{/link}的{link:humans}人类{/link}士兵正在东部边境推倒牛头人探路者的路标。]=],
		},
	},
})

Translate("zhCN", "ratchet", {
	title = "棘齿城",
	sections = {
		{
			title = "概述",
			text = [=[棘齿城是{link:the-barrens}贫瘠之地{/link}东岸的一座地精港口，位于{link:the-merchant-coast}商旅海岸{/link}的边缘。地精{link:gazlowe}加兹鲁维{/link}用建造{link:orgrimmar}奥格瑞玛{/link}赚来的{link:ginro-hearthkindle}金{/link}子建起了它，它隶属于{link:steamwheedle-cartel}热砂港{/link}。在这里，{link:orcs}兽人{/link}与{link:humans}人类{/link}可以并肩买卖，因为城中的打手以铁腕维持和平。船只从它的码头出发，渡海驶往{link:booty-bay}藏宝海湾{/link}。它的工匠制造伐木机，酿酒师保存着古老的配方，商人则追逐每一条发财的传闻，从{link:the-sludge-fen}淤泥沼泽{/link}一直追到{link:wailing-caverns}哀嚎洞穴{/link}。海盗与鲨鱼是它仅有的真正敌人，而这两者它都不缺。]=],
		},
	},
})

Translate("zhCN", "northwatch-hold", {
	title = "北方城堡",
	aliases = { "北方要塞" },
	sections = {
		{
			title = "概述",
			text = [=[北方城堡是{link:alliance}联盟{/link}的一座石砌要塞，建在{link:the-merchant-coast}商旅海岸{/link}南段上方的山丘上。{link:battle-of-mount-hyjal}海加尔山之战{/link}后由{link:humans}人类{/link}建造，{link:daelin-proudmoore}戴林·普罗德摩尔{/link}海军上将曾在对{link:horde}部落{/link}的战争中利用过它。如今，{link:theramore-isle}塞拉摩{/link}的士兵在{link:captain-fairmount}法莫斯队长{/link}的指挥下驻守于此。这里的海军陆战队神经紧张，动辄开火。他们的火炮击沉过不止一艘驶向{link:ratchet}棘齿城{/link}的船，他们还关押着被称为联盟威胁的囚犯，其中有些不过是水手。在{link:orcs}兽人{/link}眼中，它的城墙是一支指向{link:the-barrens}贫瘠之地{/link}心脏的长矛。]=],
		},
	},
})

Translate("zhCN", "far-watch-post", {
	title = "前沿哨所",
	sections = {
		{
			title = "概述",
			text = [=[前沿哨所位于{link:the-barrens}贫瘠之地{/link}东缘，靠近跨越怒水河通往{link:durotar}杜隆塔尔{/link}的桥。这是一座小小的{link:orcs}兽人{/link}营地，有一座瞭望塔和几架投石车，也是新兵离开兽人故土后抵达的第一个哨所。{link:kaga-wildhoof}卡加{/link}尔·战痕签署他们的文书，把他们送往{link:the-crossroads}十字路口{/link}。战士犹塞克在这里考验{link:horde}部落{/link}的年轻战士，而术士{link:neeru-fireblade}尼尔鲁·火刃{/link}的代理人雅克塞罗斯则在准备力量之石，用来对付{link:dreadmist-peak}鬼雾峰{/link}的恶魔。]=],
		},
	},
})

Translate("zhCN", "the-mor-shan-rampart", {
	title = "莫尔杉壁垒",
	aliases = { "莫尔杉" },
	sections = {
		{
			title = "概述",
			text = [=[莫尔杉壁垒是一道木石筑成的墙垣，位于{link:gold-road}黄金之路{/link}北端，{link:the-barrens}贫瘠之地{/link}的草原在此与{link:ashenvale}灰谷{/link}的树林相接。它是{link:horde}部落{/link}在森林中作战的门户。战歌氏族的{link:orcs}兽人{/link}在灰谷伐木，{link:night-elves}暗夜精灵{/link}则以箭矢回应每一把斧头。卡德拉克在{link:the-bulwark}壁垒{/link}的瞭望塔上指挥灰谷战事。他派信使前往{link:the-zoram-strand}佐拉姆海岸{/link}和{link:splintertree-post}碎木岗哨{/link}的新前哨，再把他们的报告带回来。]=],
		},
	},
})

Translate("zhCN", "lushwater-oasis", {
	title = "甜水绿洲",
	aliases = { "甜水" },
	sections = {
		{
			title = "概述",
			text = [=[甜水绿洲位于{link:the-crossroads}十字路口{/link}以南，是干草中的一片棕榈与水塘。它是近年来从{link:the-barrens}贫瘠之地{/link}地下涌出的新绿洲之一。绿洲北侧耸立着一座岩石山丘，山中开着{link:wailing-caverns}哀嚎洞穴{/link}的入口，风声日夜从中呜咽而出。{link:hezrul-bloodmark}赫兹鲁尔·血印{/link}率领的{link:kolkar-centaurs}科卡尔半人马{/link}在水边扎营。德鲁伊{link:naralex}纳拉雷克斯{/link}的两名门徒在洞穴上方的山丘上守望，而在这里饮水的野兽已开始变得古怪。]=],
		},
	},
})

Translate("zhCN", "the-stagnant-oasis", {
	title = "死水绿洲",
	sections = {
		{
			title = "概述",
			text = [=[死水绿洲位于{link:the-crossroads}十字路口{/link}东南，是草原中一潭静止而浑浊的水。{link:kolkar-centaurs}科卡尔半人马{/link}在岸边搭起了一座指挥帐篷，当部族召唤时，{link:verog-the-dervish}狂热的维罗戈{/link}便会前来。水下大地的一道裂隙中蕴藏着一股奇异的力量。投入其中的干枯死种竟复活了。池中钳嘴龟的甲壳带有一种德鲁伊从未见过的污染。绿洲以南是阳鳞迅猛龙的巢穴。]=],
		},
	},
})

Translate("zhCN", "the-forgotten-pools", {
	title = "遗忘之池",
	sections = {
		{
			title = "概述",
			text = [=[遗忘之池位于{link:the-crossroads}十字路口{/link}西北，西路以北。它们是{link:the-barrens}贫瘠之地{/link}最北的绿洲。池水之下的大地裂开一道缝隙，气体从中不断冒出。正是在这里，德鲁伊{link:tonga-runetotem}图加·符文图腾{/link}首次发现了那股渗入大地的力量的迹象。{link:kolkar-centaurs}科卡尔半人马{/link}在池边游荡，他们的首领{link:barak-kodobane}巴拉克·科多班恩{/link}在附近扎营。]=],
		},
	},
})

Translate("zhCN", "field-of-giants", {
	title = "巨人旷野",
	sections = {
		{
			title = "概述",
			text = [=[巨人旷野覆盖着{link:the-barrens}贫瘠之地{/link}南部的{link:burning-steppes}平原{/link}，位于{link:camp-taurajo}陶拉祖营地{/link}与{link:dustwallow-marsh}尘泥沼泽{/link}边界之间。干土筑成的高塔从草丛中拔地而起，远远望去，宛如静立的巨人。{link:farmer-ray}雷{/link}霆蜥蜴和科多兽在其间吃草。近来，一种名为{link:qiraji}异种蝎{/link}的虫形生物出现在旷野中。它们挖掘巢穴，产下虫卵，似乎还会以野兽不该有的方式思考。{link:the-crossroads}十字路口{/link}的考兰为他在{link:orgrimmar}奥格瑞玛{/link}的主人研究它们，猎人{link:jorn-skyseer}乔恩·星眼{/link}则担心它们预示着严酷的未来。]=],
		},
	},
})

Translate("zhCN", "bael-modan", {
	title = "巴尔莫丹",
	aliases = { "巴尔丹城堡" },
	sections = {
		{
			title = "概述",
			text = [=[巴尔莫丹是{link:the-barrens}贫瘠之地{/link}最南端的一处{link:dwarves}矮人{/link}挖掘场，由巴尔丹城堡的石墙守护。矮人在大地上炸出深坑，他们的机器撕扯着山丘。他们的飞行器在上空盘旋。他们挖掘的这片土地曾是石塔{link:tauren}牛头人{/link}的家园，对他们而言是神圣之地。这个部族被赶走了，只剩流浪者{link:gann-stonespire}加恩·石塔{/link}仍在附近的道路上行走，寻求复仇。这次挖掘的第一件重大发现是一块名为“月之泪”的宝石。矮人的将军认定它受了诅咒，将它锁了起来。]=],
		},
	},
})

Translate("zhCN", "dreadmist-peak", {
	title = "鬼雾峰",
	sections = {
		{
			title = "概述",
			text = [=[鬼雾峰耸立在{link:the-crossroads}十字路口{/link}西北，峰顶笼罩着一层红雾。{link:burning-blade}火刃氏族{/link}的邪教徒占据着它的高处。在靠近山顶的一个洞穴里，一座火焰祭坛之上，他们保管着恶魔种子，那是{link:burning-legion}燃烧军团{/link}的工具。峰顶的水池影响着北部{link:burning-steppes}平原{/link}的天气，德鲁伊们担心邪教徒已经毒害了它们，而在平原瞪羚中蔓延的疾病正是从那里开始的。就连{link:orgrimmar}奥格瑞玛{/link}的{link:neeru-fireblade}尼尔鲁·火刃{/link}也要求摧毁那颗种子。据说在{link:third-war}第三次战争{/link}后的岁月里，{link:jaina-proudmoore}吉安娜·普罗德摩尔{/link}本人曾在这座山峰上与一个恶魔交战。]=],
		},
	},
})

Translate("zhCN", "blackthorn-ridge", {
	title = "黑棘山",
	sections = {
		{
			title = "概述",
			text = [=[黑棘山是{link:the-barrens}贫瘠之地{/link}南部一座荆棘丛生的{link:stranglethorn-vale}山谷{/link}，位于{link:razorfen-kraul}剃刀沼泽{/link}巨大巢穴的北面。{link:bristleback-quilboar}钢鬃野猪人{/link}占据着这里。三名首领从剃刀沼泽中走出，指挥他们对{link:horde}部落{/link}的战争：先知{link:nak}纳克{/link}、追踪者库兹和他们的督军{link:lok-orcbane}洛克·奥克班恩{/link}。他们的营地散布在荆棘之间。在山谷上方的山岭上，{link:orcs}兽人{/link}萨满布瑞恩在一汪纯净的水池旁守着一座孤零零的营地，向部落的年轻萨满传授水之召唤。]=],
		},
	},
})

Translate("zhCN", "honor-s-stand", {
	title = "荣耀岗哨",
	sections = {
		{
			title = "概述",
			text = [=[荣耀岗哨位于{link:the-barrens}贫瘠之地{/link}的西路上，那里的道路向{link:stonetalon-mountains}石爪山脉{/link}攀升。没有史书记载是谁为它命名，也不知它纪念的是哪一场坚守。两名{link:horde}部落{/link}旅人在这里的路边扎营。{link:seereth-stonebreak}希雷斯·碎石{/link}是一位萨满，她听见石爪山脉的灵魂在呼喊，控诉{link:venture-company}风险投资公司{/link}。{link:makaba-flathoof}玛卡巴·扁蹄{/link}是一个{link:tauren}牛头人{/link}，他的村庄被{link:grimtotem-clan}恐怖图腾{/link}焚毁，他只想看到更多恐怖图腾死去。]=],
		},
	},
})

Translate("zhCN", "the-merchant-coast", {
	title = "商旅海岸",
	sections = {
		{
			title = "概述",
			text = [=[商旅海岸是{link:the-barrens}贫瘠之地{/link}的东部海岸，从{link:ratchet}棘齿城{/link}向南直到{link:northwatch-hold}北方城堡{/link}的城墙。它的名字来自流经这座地精港口的贸易。在棘齿城以南，{link:southsea-pirates}南海海盗{/link}在海滩上建起了营地。他们劫掠{link:gazlowe}加兹鲁维{/link}和贸易亲王们的船只，听命于“鲁莽”号的船长{link:baron-longshore}巴隆·朗绍尔{/link}。棘齿城的一名工匠曾派出一台机器去对付他们。那台机器再也没有回来。如今它的零件散落在海盗营地各处。]=],
		},
	},
})

Translate("zhCN", "boulder-lode-mine", {
	title = "石矿洞",
	sections = {
		{
			title = "概述",
			text = [=[石矿洞位于{link:the-barrens}贫瘠之地{/link}的东北尽头，在{link:the-sludge-fen}淤泥沼泽{/link}以外。{link:orcs}兽人{/link}的木梁仍支撑着它的坑道，但{link:venture-company}风险投资公司{/link}已将它占为己有。消息很快传到了{link:ratchet}棘齿城{/link}，最新的消息说，一名地精矿工挖出了一块拳头大小的绿宝石。棘齿城的码头管理员认识愿意出高价的买家，而听到这个消息的并不只有他一人。]=],
		},
	},
})

Translate("zhCN", "thorn-hill", {
	title = "荆棘岭",
	sections = {
		{
			title = "概述",
			text = [=[荆棘岭耸立在{link:the-crossroads}十字路口{/link}以东，位于城镇与通往{link:durotar}杜隆塔尔{/link}的道路之间。它的山坡缠满了{link:bristleback-quilboar}钢鬃野猪人{/link}的巨大荆棘藤。劫掠者{link:kreenig-snarlsnout}克里尼格·糟鼻{/link}曾从这里袭击来自杜隆塔尔的车队，靠{link:horde}部落{/link}的补给养得膘肥体壮。更可怕的东西潜伏在{link:razorfen-downs}高地{/link}上的一个洞穴里。{link:quilboar}野猪人{/link}说起{link:chol-aruk}吞噬者{/link}乔拉鲁克，一头与他们同族的怪物，在战士们进洞寻找它之前，没有人相信它的存在。]=],
		},
	},
})

Translate("zhCN", "raptor-grounds", {
	title = "迅猛龙巢穴",
	sections = {
		{
			title = "概述",
			text = [=[迅猛龙巢穴是{link:ratchet}棘齿城{/link}以南、{link:northwatch-hold}北方城堡{/link}以西的一座小{link:stranglethorn-vale}山谷{/link}。阳鳞迅猛龙在这里筑巢，它们的狡猾远超迅猛龙应有的程度。它们从{link:the-crossroads}十字路口{/link}的守卫塔偷走了一批银子，那是士兵们的军饷，并把它带回了巢穴。没有人知道迅猛龙要银子做什么。地精麦伯克·米希瑞克斯认为它们的狡黠藏在角里。]=],
		},
	},
})

Translate("zhCN", "the-sludge-fen", {
	title = "淤泥沼泽",
	sections = {
		{
			title = "概述",
			text = [=[淤泥沼泽位于{link:the-barrens}贫瘠之地{/link}东北部。{link:venture-company}风险投资公司{/link}在上面竖起了一座油井架，原本的水塘如今成了一片黑色淤泥的泥沼。监工鲁格维兹在井架顶上掌管工程，地精伐木机在岸边巡行。{link:ratchet}棘齿城{/link}的工匠们嫉妒这家公司的新机器。其中一人维兹克兰克潜入其中想偷一台伐木机，却为时已晚地发现自己没有让它行走的钥匙。]=],
		},
	},
})

Translate("zhCN", "agama-gor", {
	title = "阿迦玛戈",
	sections = {
		{
			title = "概述",
			text = [=[阿迦玛戈是{link:bristleback-quilboar}刺背野猪人{/link}位于{link:the-barrens}贫瘠之地{/link}中部的一座营地，在{link:camp-taurajo}陶拉祖营地{/link}向西的道路以北。营中的地卜师从土中挖出血红色的石头，{link:quilboar}野猪人{/link}把它们当作力量的图腾随身携带。来自陶拉祖营地的步兵曾在这里作战，并非每次都能归来。其中一人，步兵多格兰，负伤躺在营地附近，他的战友们则去寻求治疗。在道路对面，{link:bramblescar}迅猛龙平原{/link}的钢鬃野猪人怀着仇恨注视着刺背野猪人。]=],
		},
	},
})

Translate("zhCN", "bramblescar", {
	title = "迅猛龙平原",
	sections = {
		{
			title = "概述",
			text = [=[迅猛龙平原是{link:bristleback-quilboar}钢鬃野猪人{/link}在{link:the-barrens}贫瘠之地{/link}中部的一座荆棘营地，位于{link:the-crossroads}十字路口{/link}与{link:camp-taurajo}陶拉祖营地{/link}之间道路的东侧。这里的钢鬃野猪人与道路对面{link:agama-gor}阿迦玛戈{/link}的刺背{link:quilboar}野猪人{/link}交战，也攻击任何靠近的人。附近一座小小的{link:tauren}牛头人{/link}营地里，{link:orcs}兽人{/link}{link:mankrik}曼科里克{/link}和他的妻子并肩打了最后一仗。曼科里克相信，是这一带的钢鬃劫掠者夺走了她佩戴的骨制珠宝。]=],
		},
	},
})

Translate("zhCN", "gold-road", {
	title = "黄金之路",
	aliases = { "南黄金之路" },
	sections = {
		{
			title = "概述",
			text = [=[黄金之路是{link:the-barrens}贫瘠之地{/link}的大道。它从北方的{link:the-mor-shan-rampart}莫尔杉壁垒{/link}出发，经过{link:the-crossroads}十字路口{/link}和{link:camp-taurajo}陶拉祖营地{/link}，一直通到南方{link:thousand-needles}千针石林{/link}边缘的{link:the-great-lift}升降梯{/link}。它的名字来自往来其上的商队。它的北段有{link:horde}部落{/link}的塔楼守望。南段则更为荒凉，黄昏时偏离大道的行人，可能最终会困在树上，下面有鬣狗在打转。]=],
		},
	},
})

Translate("zhCN", "the-dry-hills", {
	title = "无水岭",
	sections = {
		{
			title = "概述",
			text = [=[无水岭耸立在{link:the-barrens}贫瘠之地{/link}的西北尽头，是{link:stonetalon-mountains}石爪山脉{/link}青翠的山麓。巫翼{link:harpies}鹰身人{/link}在塞瑞娜·血羽的率领下在此筑巢，俯冲袭击北路上的商队。在山丘上方的一道山岭上，住着一位名叫{link:walton}沃尔顿{/link}的隐居皮匠，他不愿与人往来。猎人{link:vrang-wildgore}弗朗恩·凝血{/link}在下方的{link:stranglethorn-vale}山谷{/link}里设置陷阱。近来，有人看见身穿{link:kul-tiras}库尔提拉斯{/link}号衣的人在那座山谷里搜寻，在一辆损毁的大车旁扎营。]=],
		},
	},
})

Translate("zhCN", "grol-dom-farm", {
	title = "格罗多姆农场",
	sections = {
		{
			title = "概述",
			text = [=[格罗多姆农场是{link:orcs}兽人{/link}的一座养猪场，位于{link:the-crossroads}十字路口{/link}与{link:durotar}杜隆塔尔{/link}之间的路上，是{link:orgrimmar}奥格瑞玛{/link}建立以来兴起的众多农场之一。这是一个满是猪圈与猪群的安静地方。它的主人卡纳尔·菲斯是{link:horde}部落{/link}的一位萨满。他把想要驾驭火焰的人送往杜隆塔尔的一座隐秘神龛，并要他们把点燃的火炬带回来给他。]=],
		},
	},
})

Translate("zhCN", "fray-island", {
	title = "勇士岛",
	sections = {
		{
			title = "概述",
			text = [=[勇士岛是{link:the-barrens}贫瘠之地{/link}东岸外一座干燥的小岛。岛主克兰诺克·马克{link:farmer-ray}雷{/link}德自称“岛民”，他为各个种族的战士开设了一座实验场。想要向他学艺的人必须先通过“混战”：他们走进人群中央，与一个又一个挑战者搏斗，直到冠军出场迎战。]=],
		},
	},
})

