	subtitle = "十字路口的药剂师",
	found = "十字路口",
	hint = "与在十字路口工作的被遗忘者药剂师交谈。",
	allegiance = "皇家药剂师协会 · 被遗忘者",
	aliases = { "赫布瑞姆" },
	sections = {
		{
			title = "概述",
			text = [=[药剂师赫布瑞姆是{link:royal-apothecary-society}皇家药剂师协会{/link}的一名{link:forsaken}被遗忘者{/link}，被派离{link:lordaeron}洛丹伦{/link}，远赴{link:the-crossroads}十字路口{/link}工作。他研究家乡的毒素会对{link:kalimdor}卡利姆多{/link}的野兽产生什么作用。他也被绿洲所吸引，那里的水会改变每一株饮用它的植物和每一只饮用它的生物。他说，被遗忘者信守契约，他会付钱给为他带来所需之物的人。]=],
		},
