			hint = "领取海盗男爵的悬赏。",
			text = [=[加兹鲁维悬赏缉拿{link:southsea-pirates}南海海盗{/link}的首领、{link:gilneas}吉尔尼斯{/link}人{link:baron-longshore}巴隆·朗绍尔{/link}，并要求他的遗骸保持在能被认出的状态。事成之后，他承认自己曾看着{link:the-baron}男爵{/link}的船在开阔的海面上滑行，觉得那是一幅美景。]=],
		},
		{
			title = "鲨鱼",
			hint = "响应棘齿城张贴的招募垂钓者告示。",
