			hint = "找回曼科里克妻子的饰物。",
			text = [=[救了曼科里克的治疗者没能救下她。她的名字叫{link:olgra}奥尔格拉{/link}。她曾佩戴许多抛光骨头制成的珠宝，都是她亲手制作的艺术品，而这些珠宝已从她身上消失。曼科里克请求从夺走它们的{link:bristleback-quilboar}钢鬃野猪人{/link}手中把它们夺回，好让他把它们放在她的纪念碑上，永远不忘记她。]=],
