	aliases = { "科卡尔", "科卡尔部族" },
	sections = {
		{
			title = "概述",
			text = [=[科卡尔是一个{link:centaurs}半人马{/link}部族，在{link:the-barrens}贫瘠之地{/link}及其周边地区游荡。他们的骑手在绿洲旁扎营，猎杀前来饮水的野兽，并袭击道路上的旅人。在{link:orcs}兽人{/link}到来之前，他们袭扰{link:tauren}牛头人{/link}多年，此后又一直袭扰{link:horde}部落{/link}。]=],
		},
		{
			title = "如今",
			text = [=[长久以来，{link:the-barrens}贫瘠之地{/link}的科卡尔四散无序。如今，他们中崛起了新的首领：{link:the-forgotten-pools}遗忘之池{/link}附近的{link:barak-kodobane}巴拉克·科多班恩{/link}，{link:the-stagnant-oasis}死水绿洲{/link}的{link:verog-the-dervish}狂热的维罗戈{/link}，以及其中最强大的、在{link:lushwater-oasis}甜水绿洲{/link}的{link:hezrul-bloodmark}赫兹鲁尔·血印{/link}。在这些酋长的统领下，这个部族已成为真正的威胁。{link:regthar-deathgate}雷戈萨·死门{/link}从{link:the-crossroads}十字路口{/link}以西的碉堡追猎他们，当他们的首领倒下时，一支战团从科卡尔位于{link:desolace}凄凉之地{/link}的故乡赶来复仇。在{link:durotar}杜隆塔尔{/link}，另一伙科卡尔占据着岩石峡谷{link:kolkar-crag}科卡尔峭壁{/link}。]=],
		},
	},
})

